import React from "react";
import { Link } from "react-router-dom";

const Home = () => {
  return (
    <div style={{ maxWidth: "1100px", margin: "auto", padding: "20px" }}>

      {/* HERO SECTION */}
      <section
        style={{
          background: "linear-gradient(135deg, #ffe6f0, #e6f7ff)",
          padding: "80px 20px",
          borderRadius: "25px",
          textAlign: "center",
          marginBottom: "60px",
        }}
      >
        <h1
          style={{
            fontSize: "40px",
            color: "#ff4f87",
            marginBottom: "15px",
          }}
        >
          Nanhe Farishte – Kiran Knits
        </h1>

        <p style={{ fontSize: "18px", marginBottom: "30px", color: "#555" }}>
          Har bunai mein maa ka pyaar 💖
        </p>

        <Link to="/products">
          <button
            style={{
              background: "#6ec6ff",
              border: "none",
              padding: "12px 35px",
              borderRadius: "30px",
              color: "white",
              fontSize: "16px",
              cursor: "pointer",
              transition: "0.3s ease",
            }}
            onMouseOver={(e) =>
              (e.target.style.background = "#4fb3f6")
            }
            onMouseOut={(e) =>
              (e.target.style.background = "#6ec6ff")
            }
          >
            Shop Now
          </button>
        </Link>
      </section>

      {/* CATEGORIES SECTION */}
      <section>
        <h2
          style={{
            textAlign: "center",
            marginBottom: "40px",
            fontSize: "28px",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "30px",
            flexWrap: "wrap",
          }}
        >
          {/* Sweater */}
          <Link
            to="/products?category=Sweater"
            style={{ textDecoration: "none" }}
          >
            <div style={cardStyle}>🧥 Sweaters</div>
          </Link>

          {/* Socks */}
          <Link
            to="/products?category=Socks"
            style={{ textDecoration: "none" }}
          >
            <div style={cardStyle}>🧦 Socks</div>
          </Link>

          {/* Cap */}
          <Link
            to="/products?category=Cap"
            style={{ textDecoration: "none" }}
          >
            <div style={cardStyle}>🧢 Caps</div>
          </Link>
        </div>
      </section>
    </div>
  );
};

/* CARD STYLE */
const cardStyle = {
  background: "white",
  padding: "40px 30px",
  borderRadius: "20px",
  textAlign: "center",
  fontSize: "18px",
  fontWeight: "600",
  width: "180px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
  transition: "0.3s ease",
  color: "#444",
  cursor: "pointer",
};

export default Home;
